const q = parseInt(readLine());
const mins = [];
const out = [];
for (let i = 0; i < q; i++) {
  const p = readLine().trim().split(/\s+/);
  if (p[0] === 'push') {
    const x = Number(p[1]);
    mins.push(mins.length ? Math.min(x, mins[mins.length - 1]) : x);
  } else if (p[0] === 'pop') {
    mins.pop();
  } else {
    out.push(mins[mins.length - 1]);
  }
}
console.log(out.join('\n'));

solutions.java:
import java.util.*;
import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int q = Integer.parseInt(br.readLine().trim());
        long[] mins = new long[q + 1];
        int top = 0;
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < q; i++) {
            StringTokenizer tk = new StringTokenizer(br.readLine());
            String op = tk.nextToken();
            if (op.equals("push")) {
                long x = Long.parseLong(tk.nextToken());
                mins[top] = top > 0 ? Math.min(x, mins[top - 1]) : x;
                top++;
            } else if (op.equals("pop")) {
                top--;
            } else {
                sb.append(mins[top - 1]).append('\n');
            }
        }
        System.out.print(sb);
    }
}

