#include <bits/stdc++.h>
using namespace std;
int main() {
    int q;
    cin >> q;
    vector<long long> mins;
    while (q--) {
        string op;
        cin >> op;
        if (op == "push") {
            long long x;
            cin >> x;
            mins.push_back(mins.empty() ? x : min(x, mins.back()));
        } else if (op == "pop") {
            mins.pop_back();
        } else {
            cout << mins.back() << "\n";
        }
    }
    return 0;
}
